export const ICON_CATEGORIES = ["ai", "arrows_ui", "buildings", "business", "cloud", "communication", "data", "development", "devices", "documents", "energy", "feedback", "finance", "global", "healthcare", "infrastructure", "interface", "logistics", "misc", "people", "process", "security", "services", "shopping", "telecom", "time"];

export const ICONS_BY_CATEGORY = Object.entries(ICON_MAP).reduce((acc, [name, icon]) => {
  (acc[icon.category] = acc[icon.category] || []).push(name);
  return acc;
}, {});

export const ICON_NAMES = Object.keys(ICON_MAP).sort();
